inline void enc_operation_snapshot(std::string& out, const OperationSnapshot& v, int depth) {
    if (wire_name(v.state).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "receipt");
    out += ": ";
    enc_receipt(out, v.receipt, depth + 1);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "state");
    out += ": ";
    esc(out, std::string(wire_name(v.state)));
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "progress");
    out += ": ";
    enc_work_progress(out, v.progress, depth + 1);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "cancellation_requested");
    out += ": ";
    out += v.cancellation_requested ? "true" : "false";
    if (v.failure.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "failure");
        out += ": ";
        enc_work_failure(out, *v.failure, depth + 1);
    }
    if (!v.label.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "label");
        out += ": ";
        esc(out, v.label);
    }
    if (v.label_derived) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "label_derived");
        out += ": ";
        out += v.label_derived ? "true" : "false";
    }
    if (!v.waiting.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "waiting");
        out += ": ";
        esc(out, v.waiting);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

